  primarySoft: "#dde1ff",

  // Accent — corail chaleureux pour motivation
  accent: "#ff7a59",
  accentLight: "#ffe8e1",

  // Or pour streaks et achievements
  gold: "#f5a623",
  goldLight: "#fff5e1",

  // Texte
  text: "#1a1f36",
  textMuted: "#5f6478",
  textFaint: "#9298a8",

  // Bordures
  border: "#e8ebf3",
  borderHi: "#d4d9e8",

  // Statut
  success: "#10b981",
